    '#B49AFF',
    '#FF8296',
    '#D9F3FF',
  ];
  const actual = await page.locator('figure svg').evaluateAll((elements) =>
    elements.map((element) => ({
      fill: element.querySelector('g')?.getAttribute('fill'),
      stroke: element.querySelector('g')?.getAttribute('stroke'),
